def trigger(self, dag_id: str, session: Session = NEW_SESSION):
    """Triggers DAG Run."""
    run_id = request.values.get("run_id", "")
    origin = get_safe_url(request.values.get("origin"))
    unpause = request.values.get("unpause")
    request_conf = request.values.get("conf")
    request_execution_date = request.values.get("execution_date", default=timezone.utcnow().isoformat())
    is_dag_run_conf_overrides_params = conf.getboolean("core", "dag_run_conf_overrides_params")
    dag = get_airflow_app().dag_bag.get_dag(dag_id)
    dag_orm: DagModel = session.query(DagModel).filter(DagModel.dag_id == dag_id).first()

    # Prepare form fields with param struct details to render a proper form with schema information
    form_fields = {}
    for k, v in dag.params.items():
        form_fields[k] = v.dump()
        # If no schema is provided, auto-detect on default values
        if "schema" not in form_fields[k]:
            form_fields[k]["schema"] = {}
        if "type" not in form_fields[k]["schema"]:
            if isinstance(form_fields[k]["value"], bool):
                form_fields[k]["schema"]["type"] = "boolean"
            elif isinstance(form_fields[k]["value"], int):
                form_fields[k]["schema"]["type"] = ["integer", "null"]
            elif isinstance(form_fields[k]["value"], list):
                form_fields[k]["schema"]["type"] = ["array", "null"]
            elif isinstance(form_fields[k]["value"], dict):
                form_fields[k]["schema"]["type"] = ["object", "null"]
        # Mark markup fields as safe
        if (
            "description_html" in form_fields[k]["schema"]
            and form_fields[k]["schema"]["description_html"]
        ):
            form_fields[k]["description"] = Markup(form_fields[k]["schema"]["description_html"])
        if "custom_html_form" in form_fields[k]["schema"]:
            form_fields[k]["schema"]["custom_html_form"] = Markup(
                form_fields[k]["schema"]["custom_html_form"]
            )
    ui_fields_defined = any("const" not in f["schema"] for f in form_fields.values())

    if not dag_orm:
        flash(f"Cannot find dag {dag_id}")
        return redirect(origin)

    if dag_orm.has_import_errors:
        flash(f"Cannot create dagruns because the dag {dag_id} has import errors", "error")
        return redirect(origin)

    recent_runs = (
        session.query(
            DagRun.conf, func.max(DagRun.run_id).label("run_id"), func.max(DagRun.execution_date)
        )
        .filter(
            DagRun.dag_id == dag_id,
            DagRun.run_type == DagRunType.MANUAL,
            DagRun.conf.isnot(None),
        )
        .group_by(DagRun.conf)
        .order_by(func.max(DagRun.execution_date).desc())
        .limit(5)
    )
    recent_confs = {
        run_id: json.dumps(run_conf)
        for run_id, run_conf in ((run.run_id, run.conf) for run in recent_runs)
        if isinstance(run_conf, dict) and any(run_conf)
    }

    if request.method == "GET" and ui_fields_defined:
        # Populate conf textarea with conf requests parameter, or dag.params
        default_conf = ""

        doc_md = wwwutils.wrapped_markdown(getattr(dag, "doc_md", None))
        form = DateTimeForm(data={"execution_date": request_execution_date})

        if request_conf:
            default_conf = request_conf
        else:
            try:
                default_conf = json.dumps(
                    {str(k): v.resolve(suppress_exception=True) for k, v in dag.params.items()},
                    indent=4,
                    ensure_ascii=False,
                )
            except TypeError:
                flash("Could not pre-populate conf field due to non-JSON-serializable data-types")
        return self.render_template(
            "airflow/trigger.html",
            form_fields=form_fields,
            dag=dag,
            dag_id=dag_id,
            origin=origin,
            conf=default_conf,
            doc_md=doc_md,
            form=form,
            is_dag_run_conf_overrides_params=is_dag_run_conf_overrides_params,
            recent_confs=recent_confs,
        )

    try:
        execution_date = timezone.parse(request_execution_date)
    except ParserError:
        flash("Invalid execution date", "error")
        form = DateTimeForm(data={"execution_date": timezone.utcnow().isoformat()})
        return self.render_template(
            "airflow/trigger.html",
            form_fields=form_fields,
            dag=dag,
            dag_id=dag_id,
            origin=origin,
            conf=request_conf if request_conf else {},
            form=form,
            is_dag_run_conf_overrides_params=is_dag_run_conf_overrides_params,
            recent_confs=recent_confs,
        )

    dr = DagRun.find_duplicate(dag_id=dag_id, run_id=run_id, execution_date=execution_date)
    if dr:
        if dr.run_id == run_id:
            message = f"The run ID {run_id} already exists"
        else:
            message = f"The logical date {execution_date} already exists"
        flash(message, "error")
        return redirect(origin)

    # Flash a warning when slash is used, but still allow it to continue on.
    if run_id and "/" in run_id:
        flash(
            "Using forward slash ('/') in a DAG run ID is deprecated. Note that this character "
            "also makes the run impossible to retrieve via Airflow's REST API.",
            "warning",
        )

    run_conf = {}
    if request_conf:
        try:
            run_conf = json.loads(request_conf)
            if not isinstance(run_conf, dict):
                flash("Invalid JSON configuration, must be a dict", "error")
                form = DateTimeForm(data={"execution_date": execution_date})
                return self.render_template(
                    "airflow/trigger.html",
                    form_fields=form_fields,
                    dag=dag,
                    dag_id=dag_id,
                    origin=origin,
                    conf=request_conf,
                    form=form,
                    is_dag_run_conf_overrides_params=is_dag_run_conf_overrides_params,
                    recent_confs=recent_confs,
                )
        except json.decoder.JSONDecodeError:
            flash("Invalid JSON configuration, not parseable", "error")
            form = DateTimeForm(data={"execution_date": execution_date})
            return self.render_template(
                "airflow/trigger.html",
                form_fields=form_fields,
                dag=dag,
                dag_id=dag_id,
                origin=origin,
                conf=request_conf,
                form=form,
                is_dag_run_conf_overrides_params=is_dag_run_conf_overrides_params,
                recent_confs=recent_confs,
            )

    if unpause and dag.get_is_paused():
        dag_model = models.DagModel.get_dagmodel(dag_id)
        if dag_model is not None:
            dag_model.set_is_paused(is_paused=False)

    try:
        dag.create_dagrun(
            run_type=DagRunType.MANUAL,
            execution_date=execution_date,
            data_interval=dag.timetable.infer_manual_data_interval(run_after=execution_date),
            state=State.QUEUED,
            conf=run_conf,
            external_trigger=True,
            dag_hash=get_airflow_app().dag_bag.dags_hash.get(dag_id),
            run_id=run_id,
        )
    except (ValueError, ParamValidationError) as ve:
        flash(f"{ve}", "error")
        form = DateTimeForm(data={"execution_date": execution_date})
        # Take over "bad" submitted fields for new form display
        for k, v in form_fields.items():
            form_fields[k]["value"] = run_conf[k]
        return self.render_template(
            "airflow/trigger.html",
            form_fields=form_fields,
            dag=dag,
            dag_id=dag_id,
            origin=origin,
            conf=request_conf,
            form=form,
            is_dag_run_conf_overrides_params=is_dag_run_conf_overrides_params,
        )

    flash(f"Triggered {dag_id}, it should start any moment now.")
    return redirect(origin)

def static(path):
    """
    Create a page handler to serve static files. Disable authentication.
    """
    assert isinstance(path, str)
    assert os.path.exists(path), "%r doesn't exists" % path
    content_type = None
    if os.path.isfile(path):
        # Set content-type based on filename extension
        ext = ""
        i = path.rfind('.')
        if i != -1:
            ext = path[i:].lower()
        content_type = mimetypes.types_map.get(ext, None)  # @UndefinedVariable

    @cherrypy.expose
    @cherrypy.tools.auth_form(on=False)
    @cherrypy.tools.sessions(on=False)
    @cherrypy.tools.secure_headers(on=False)
    def handler(*args, **kwargs):
        if cherrypy.request.method not in ('GET', 'HEAD'):
            return None
        filename = os.path.join(path, *args)
        assert filename.startswith(path)
        if not os.path.isfile(filename):
            return None
        return serve_file(filename, content_type)

    return handler

def _handle_hybi_request(self, environ):
    if 'eventlet.input' in environ:
        sock = environ['eventlet.input'].get_socket()
    elif 'gunicorn.socket' in environ:
        sock = environ['gunicorn.socket']
    else:
        raise Exception('No eventlet.input or gunicorn.socket present in environ.')

    hybi_version = environ['HTTP_SEC_WEBSOCKET_VERSION']
    if hybi_version not in ('8', '13', ):
        raise BadRequest(status='426 Upgrade Required',
                         headers=[('Sec-WebSocket-Version', '8, 13')])
    self.protocol_version = int(hybi_version)
    if 'HTTP_SEC_WEBSOCKET_KEY' not in environ:
        # That's bad.
        raise BadRequest()
    origin = environ.get(
        'HTTP_ORIGIN',
        (environ.get('HTTP_SEC_WEBSOCKET_ORIGIN', '')
         if self.protocol_version <= 8 else ''))
    if self.origin_checker is not None:
        if not self.origin_checker(environ.get('HTTP_HOST'), origin):
            raise BadRequest(status='403 Forbidden')
    protocols = environ.get('HTTP_SEC_WEBSOCKET_PROTOCOL', None)
    negotiated_protocol = None
    if protocols:
        for p in (i.strip() for i in protocols.split(',')):
            if p in self.supported_protocols:
                negotiated_protocol = p
                break

    key = environ['HTTP_SEC_WEBSOCKET_KEY']
    response = base64.b64encode(sha1(six.b(key) + PROTOCOL_GUID).digest())
    handshake_reply = [b"HTTP/1.1 101 Switching Protocols",
                       b"Upgrade: websocket",
                       b"Connection: Upgrade",
                       b"Sec-WebSocket-Accept: " + response]
    if negotiated_protocol:
        handshake_reply.append(b"Sec-WebSocket-Protocol: " + six.b(negotiated_protocol))

    parsed_extensions = {}
    extensions = self._parse_extension_header(environ.get("HTTP_SEC_WEBSOCKET_EXTENSIONS"))

    deflate = self._negotiate_permessage_deflate(extensions)
    if deflate is not None:
        parsed_extensions["permessage-deflate"] = deflate

    formatted_ext = self._format_extension_header(parsed_extensions)
    if formatted_ext is not None:
        handshake_reply.append(b"Sec-WebSocket-Extensions: " + formatted_ext)

    sock.sendall(b'\r\n'.join(handshake_reply) + b'\r\n\r\n')
    return RFC6455WebSocket(sock, environ, self.protocol_version,
                            protocol=negotiated_protocol,
                            extensions=parsed_extensions)

def getvalue(self):
    data = b"".join(self.data)
    if not self.opcode & 8 and self.decompressor:
        data = self.decompressor.decompress(data + b'\x00\x00\xff\xff')
    if self.decoder:
        data = self.decoder.decode(data, self.finished)
    return data

def from_data(*, data: oai.Operation, path: str, method: str, tag: str) -> Union[Endpoint, ParseError]:
    """ Construct an endpoint from the OpenAPI data """

    if data.operationId is None:
        return ParseError(data=data, detail="Path operations with operationId are not yet supported")

    endpoint = Endpoint(
        path=path,
        method=method,
        description=data.description,
        name=data.operationId,
        requires_security=bool(data.security),
        tag=tag,
    )

    result = Endpoint._add_parameters(endpoint, data)
    if isinstance(result, ParseError):
        return result
    result = Endpoint._add_responses(result, data.responses)
    if isinstance(result, ParseError):
        return result
    result = Endpoint._add_body(result, data)

    return result

def property_from_data(
    name: str, required: bool, data: Union[oai.Reference, oai.Schema]
) -> Union[Property, PropertyError]:
    """ Generate a Property from the OpenAPI dictionary representation of it """
    if isinstance(data, oai.Reference):
        return RefProperty(name=name, required=required, reference=Reference.from_ref(data.ref), default=None)
    if data.enum:
        return EnumProperty(
            name=name,
            required=required,
            values=EnumProperty.values_from_list(data.enum),
            title=data.title or name,
            default=data.default,
        )
    if data.anyOf:
        sub_properties: List[Property] = []
        for sub_prop_data in data.anyOf:
            sub_prop = property_from_data(name=name, required=required, data=sub_prop_data)
            if isinstance(sub_prop, PropertyError):
                return PropertyError(detail=f"Invalid property in union {name}", data=sub_prop_data)
            sub_properties.append(sub_prop)
        return UnionProperty(name=name, required=required, default=data.default, inner_properties=sub_properties)
    if not data.type:
        return PropertyError(data=data, detail="Schemas must either have one of enum, anyOf, or type defined.")
    if data.type == "string":
        return _string_based_property(name=name, required=required, data=data)
    elif data.type == "number":
        return FloatProperty(name=name, default=data.default, required=required)
    elif data.type == "integer":
        return IntProperty(name=name, default=data.default, required=required)
    elif data.type == "boolean":
        return BooleanProperty(name=name, required=required, default=data.default)
    elif data.type == "array":
        if data.items is None:
            return PropertyError(data=data, detail="type array must have items defined")
        inner_prop = property_from_data(name=f"{name}_item", required=True, data=data.items)
        if isinstance(inner_prop, PropertyError):
            return PropertyError(data=inner_prop.data, detail=f"invalid data in items of array {name}")
        return ListProperty(name=name, required=required, default=data.default, inner_property=inner_prop,)
    elif data.type == "object":
        return DictProperty(name=name, required=required, default=data.default)
    return PropertyError(data=data, detail=f"unknown type {data.type}")

def values_from_list(values: List[str]) -> Dict[str, str]:
    """ Convert a list of values into dict of {name: value} """
    output: Dict[str, str] = {}

    for i, value in enumerate(values):
        if value[0].isalpha():
            key = value.upper()
        else:
            key = f"VALUE_{i}"
        if key in output:
            raise ValueError(f"Duplicate key {key} in Enum")
        output[key] = value

    return output

def __post_init__(self) -> None:
    super().__post_init__()
    if self.default is not None:
        self.default = f'"{self.default}"'

def receive_job_button(self, obj):
    user = self.request.user
    if isinstance(obj, Site):
        if not user.has_perm("dcim.add_site"):
            self.log_failure(obj=obj, message=f"User '{user}' does not have permission to add a Site.")
        else:
            self._run_site_job(obj)
    if isinstance(obj, Device):
        if not user.has_perm("dcim.add_device"):
            self.log_failure(obj=obj, message=f"User '{user}' does not have permission to add a Device.")
        else:
            self._run_device_job(obj)
    self.log_failure(obj=obj, message=f"Unable to run Job Button for type {type(obj).__name__}.")

def post(self, request, pk):
    post_data = request.POST
    job_button = JobButton.objects.get(pk=pk)
    job_model = job_button.job
    result = JobResult.enqueue_job(
        func=run_job,
        name=job_model.class_path,
        obj_type=get_job_content_type(),
        user=request.user,
        data={
            "object_pk": post_data["object_pk"],
            "object_model_name": post_data["object_model_name"],
        },
        request=copy_safe_request(request),
        commit=True,
    )
    msg = format_html('Job enqueued. <a href="{}">Click here for the results.</a>', result.get_absolute_url())
    messages.info(request=request, message=msg)
    return redirect(post_data["redirect_path"])

def authenticate(self, request, username=None, code=None, **kwargs):
    if username is None:
        username = kwargs.get(get_user_model().USERNAME_FIELD)

    if not username or not code:
        return

    try:
        user = get_user_model()._default_manager.get_by_natural_key(username)

        if not self.user_can_authenticate(user):
            return

        timeout = getattr(settings, 'NOPASSWORD_LOGIN_CODE_TIMEOUT', 900)
        timestamp = timezone.now() - timedelta(seconds=timeout)

        # We don't delete the login code when authenticating,
        # as that is done during validation of the login form
        # and validation should not have any side effects.
        # It is the responsibility of the view/form to delete the token
        # as soon as the login was successfull.
        user.login_code = LoginCode.objects.get(user=user, code=code, timestamp__gt=timestamp)

        return user

    except (get_user_model().DoesNotExist, LoginCode.DoesNotExist):
        return

def clean_code(self):
    code = self.cleaned_data['code']
    username = code.user.get_username()
    user = authenticate(self.request, **{
        get_user_model().USERNAME_FIELD: username,
        'code': code.code,
    })

    if not user:
        raise forms.ValidationError(
            self.error_messages['invalid_code'],
            code='invalid_code',
        )

    self.cleaned_data['user'] = user

    return code

def generate_code(cls):
    hash_algorithm = getattr(settings, 'NOPASSWORD_HASH_ALGORITHM', 'sha256')
    m = getattr(hashlib, hash_algorithm)()
    m.update(getattr(settings, 'SECRET_KEY', None).encode('utf-8'))
    m.update(os.urandom(16))
    if getattr(settings, 'NOPASSWORD_NUMERIC_CODES', False):
        hashed = str(int(m.hexdigest(), 16))
    else:
        hashed = m.hexdigest()
    return hashed

def create_code_for_user(cls, user, next=None):
    if not user.is_active:
        return None

    code = cls.generate_code()
    login_code = LoginCode(user=user, code=code)
    if next is not None:
        login_code.next = next
    login_code.save()
    return login_code

def init_routes(self):
    # LISTS
    wr_api_spec.set_curr_tag('Lists')

    @self.app.get('/api/v1/lists')
    @self.api(query=['user', 'coll', 'include_bookmarks'],
              resp='lists')
    def get_lists():
        user, collection = self.load_user_coll()

        include_bookmarks = request.query.getunicode('include_bookmarks') or 'all'

        lists = collection.get_lists()

        return {
            'lists': [blist.serialize(include_bookmarks=include_bookmarks)
                      for blist in lists]
        }

    @self.app.post('/api/v1/lists')
    @self.api(query=['user', 'coll', 'include_bookmarks'],
              req_desc='List properties',
              req=['title', 'desc', 'public', 'before_id'],
              resp='list')
    def add_list():
        user, collection = self.load_user_coll()

        blist = collection.create_bookmark_list(request.json)

        collection.mark_updated()

        return {'list': blist.serialize()}

    @self.app.get('/api/v1/list/<list_id>')
    @self.api(query=['user', 'coll', 'include_bookmarks'],
              resp='list')
    def get_list(list_id):
        user, collection, blist = self.load_user_coll_list(list_id)

        self.access.assert_can_read_list(blist)

        include_bookmarks = request.query.getunicode('include_bookmarks') or 'all'

        return {'list': blist.serialize(check_slug=list_id,
                                        include_bookmarks=include_bookmarks)}

    @self.app.post('/api/v1/list/<list_id>')
    @self.api(query=['user', 'coll'],
              req_desc='Update List properties',
              req=['title', 'desc', 'public'],
              resp='list')
    def update_list(list_id):
        user, collection, blist = self.load_user_coll_list(list_id)

        blist.update(request.json)

        blist.mark_updated()
        return {'list': blist.serialize()}

    @self.app.delete('/api/v1/list/<list_id>')
    @self.api(query=['user', 'coll'],
              resp='deleted')
    def delete_list(list_id):
        user, collection, blist = self.load_user_coll_list(list_id)

        if collection.remove_list(blist):
            collection.mark_updated()
            return {'deleted_id': list_id}
        else:
            self._raise_error(400, 'error_deleting')

    @self.app.post('/api/v1/list/<list_id>/move')
    @self.api(query=['user', 'coll'],
              req=['before_id'],
              resp='success')
    def move_list_before(list_id):
        user, collection, blist = self.load_user_coll_list(list_id)

        before_id = request.json.get('before_id')

        if before_id:
            before = self.load_list(collection, before_id)
        else:
            before = None

        blist.mark_updated()
        collection.move_list_before(blist, before)
        return {'success': True}

    @self.app.post('/api/v1/lists/reorder')
    @self.api(query=['user', 'coll'],
              req_desc='An array of existing list ids in a new order',
              req=['order'],
              resp='success')
    def reorder_lists():
        user, collection = self.load_user_coll()

        new_order = request.json.get('order', [])

        if collection.lists.reorder_objects(new_order):
            collection.mark_updated()
            return {'success': True}
        else:
            return self._raise_error(400, 'invalid_order')


    #BOOKMARKS
    wr_api_spec.set_curr_tag('Bookmarks')

    @self.app.post('/api/v1/list/<list_id>/bookmarks')
    @self.api(query=['user', 'coll'],
              req_desc='Bookmark properties',
              req=['title', 'url', 'timestamp', 'browser', 'desc', 'page_id', 'before_id'],
              resp='bookmark')
    def create_bookmark(list_id):
        user, collection, blist = self.load_user_coll_list(list_id)

        bookmark = blist.create_bookmark(request.json)
        if bookmark:
            blist.mark_updated()
            return {'bookmark': bookmark}
        else:
            return self._raise_error(400, 'invalid_page')

    @self.app.post('/api/v1/list/<list_id>/bulk_bookmarks')
    @self.api(query=['user', 'coll'],
              req_desc='List of Bookmarks',
              req={'type': 'array', 'item_type': ['title', 'url', 'timestamp', 'browser', 'desc', 'page_id', 'before_id']},
              resp='list')
    def create_bookmarks(list_id):
        user, collection, blist = self.load_user_coll_list(list_id)

        bookmark_list = request.json

        blist.add_bookmarks(bookmark_list)

        return {'success': True}

    @self.app.get('/api/v1/list/<list_id>/bookmarks')
    @self.api(query=['user', 'coll'],
              resp='bookmarks')
    def get_bookmarks(list_id):
        user, collection, blist = self.load_user_coll_list(list_id)

        bookmarks = blist.get_bookmarks()

        return {'bookmarks': bookmarks}

    @self.app.get('/api/v1/bookmark/<bid>')
    @self.api(query=['user', 'coll', 'list'],
              resp='bookmark')
    def get_bookmark(bid):
        user, collection, blist = self.load_user_coll_list()

        bookmark = blist.get_bookmark(bid)
        return {'bookmark': bookmark}

    @self.app.post('/api/v1/bookmark/<bid>')
    @self.api(query=['user', 'coll', 'list'],
              req_desc='Bookmark properties',
              req=['title', 'url', 'timestamp', 'browser', 'desc', 'page_id', 'before_id'],
              resp='bookmark')
    def update_bookmark(bid):
        user, collection, blist = self.load_user_coll_list()

        bookmark = blist.update_bookmark(bid, request.json)

        blist.mark_updated()
        return {'bookmark': bookmark}

    @self.app.delete('/api/v1/bookmark/<bid>')
    @self.api(query=['user', 'coll', 'list'],
              resp='deleted')
    def delete_bookmark(bid):
        user, collection, blist = self.load_user_coll_list()
        if blist.remove_bookmark(bid):
            blist.mark_updated()
            return {'deleted_id': bid}
        else:
            self._raise_error(404, 'no_such_bookmark')

    @self.app.post('/api/v1/list/<list_id>/bookmarks/reorder')
    @self.api(query=['user', 'coll'],
              req_desc='An array of existing bookmark ids in a new order',
              req=['order'],
              resp='success')
    def reorder_bookmarks(list_id):
        user, collection, blist = self.load_user_coll_list(list_id)

        new_order = request.json.get('order', [])

        if blist.reorder_bookmarks(new_order):
            blist.mark_updated()
            return {'success': True}
        else:
            self._raise_error(400, 'invalid_order')

    wr_api_spec.set_curr_tag(None)

def init_routes(self):
    wr_api_spec.set_curr_tag('Recordings')

    @self.app.post('/api/v1/recordings')
    @self.api(query=['user', 'coll'],
              req=['title', 'desc'],
              resp='recording')
    def create_recording():
        user, collection = self.load_user_coll()

        data = request.json or {}

        title = data.get('title', '')
        desc = data.get('desc', '')

        recording = collection.create_recording(title=title, desc=desc)

        collection.mark_updated()

        return {'recording': recording.serialize()}

    @self.app.get('/api/v1/recordings')
    @self.api(query=['user', 'coll'],
              resp='recordings')
    def get_recordings():
        user, collection = self.load_user_coll()

        recs = collection.get_recordings()

        return {'recordings': [rec.serialize() for rec in recs]}

    @self.app.get('/api/v1/recording/<rec>')
    @self.api(query=['user', 'coll'],
              resp='recording')
    def get_recording(rec):
        user, collection, recording = self.load_recording(rec)

        if recording:
            return {'recording': recording.serialize()}
        else:
            self._raise_error(404, 'no_such_recording')

    @self.app.post('/api/v1/recording/<rec>')
    @self.api(query=['user', 'coll'],
              req=['desc'],
              resp='recording')
    def update_rec_desc(rec):
        user, collection, recording = self.load_recording(rec)

        user.access.assert_can_write_coll(collection)

        data = request.json or {}

        desc = data.get('desc', '')

        recording['desc'] = desc

        recording.mark_updated()
        return {'recording': recording.serialize()}

    @self.app.delete('/api/v1/recording/<rec>')
    @self.api(query=['user', 'coll'],
              resp='deleted')
    def delete_recording(rec):
        user, collection, recording = self.load_recording(rec)

        errs = collection.remove_recording(recording, delete=True)
        if errs.get('error'):
            return self._raise_error(400, errs['error'])
        else:
            return {'deleted_id': rec}

    @self.app.post('/api/v1/recording/<rec>/move/<new_coll_name>')
    @self.api(query=['user', 'coll'],
              resp='rec_move')
    def move_recording(rec, new_coll_name):
        user, collection, recording = self.load_recording(rec)

        new_collection = user.get_collection_by_name(new_coll_name)
        if not new_collection:
            self._raise_error(400, 'no_such_collection')

        user.access.assert_can_admin_coll(new_collection)

        new_rec = collection.move_recording(recording, new_collection)

        if new_rec:
            collection.mark_updated()
            new_collection.mark_updated()
            return {'coll_id': new_coll_name, 'rec_id': new_rec}
        else:
            self._raise_error(400, 'move_error')

    @self.app.post('/api/v1/recording/<rec>/copy/<new_coll_name>')
    @self.api(query=['user', 'coll'],
              resp='recording')
    def copy_recording(rec, new_coll_name):
        user, collection, recording = self.load_recording(rec)

        new_collection = user.get_collection_by_name(new_coll_name)
        if not new_collection:
            return self._raise_error(400, 'no_such_collection')

        user.access.assert_can_write_coll(collection)
        user.access.assert_can_admin_coll(new_collection)

        new_rec = new_collection.create_recording()

        if new_rec.copy_data_from_recording(recording):
            new_rec.mark_updated()
            return {'recording': new_rec.serialize()}
        else:
            return self._raise_error(400, 'copy_error')

    @self.app.post('/api/v1/recording/<rec>/pages')
    @self.api(query=['user', 'coll'],
              req=['url', 'timestamp', 'title', 'browser'],
              resp='page_id')
    def add_page(rec):
        user, collection, recording = self.load_recording(rec)

        page_data = request.json or {}

        page_id = collection.add_page(page_data, recording)
        recording.mark_updated()
        return {'page_id': page_id}

    @self.app.get('/api/v1/recording/<rec>/pages')
    @self.api(query=['user', 'coll'],
              resp='pages')
    def list_pages(rec):
        user, collection, recording = self.load_recording(rec)

        pages = collection.list_rec_pages(recording)
        return {'pages': pages}

    @self.app.get('/api/v1/recording/<rec>/num_pages')
    @self.api(query=['user', 'coll'],
              resp='count_pages')
    def get_num_pages(rec):
        user, collection, recording = self.load_recording(rec)

        return {'count': recording.count_pages() }

    @self.app.delete('/api/v1/recording/<rec>/pages')
    @self.api(query=['user', 'coll'],
              resp='deleted')
    def delete_page(rec):
        user, collection, recording = self.load_recording(rec)

        url = request.json.get('url')
        ts = request.json.get('timestamp')

        return recording.delete_page(url, ts)

    wr_api_spec.set_curr_tag(None)

def get_user_or_raise(self, username=None, status=403, msg='unauthorized'):
    # ensure correct host
    if self.app_host and request.environ.get('HTTP_HOST') != self.app_host:
        return self._raise_error(403, 'unauthorized')

    # if no username, check if logged in
    if not username:
        if self.access.is_anon():
            self._raise_error(status, msg)
        return

    user = self.get_user(user=username)

    # check permissions
    if not self.access.is_logged_in_user(user) and not self.access.is_superuser():
        self._raise_error(status, msg)

    return user

def user_attr_changed(self, userobj, attrs={}):
    if not self.send_changed:
        return

    # Leave if the mail was not changed.
    if 'email' not in attrs:
        return

    old_email = attrs['email'][0]
    if not old_email:
        logger.info("can't sent mail to user [%s] without an email", userobj.username)
        return

    # If the email attributes was changed, send a mail notification.
    body = self.app.templates.compile_template(
        "email_changed.html", **{"header_name": self.app.cfg.header_name, 'user': userobj}
    )
    self.bus.publish('queue_mail', to=old_email, subject=_("Email address changed"), message=body)

def trigger(self, session: Session = NEW_SESSION):
    """Triggers DAG Run."""
    dag_id = request.values["dag_id"]
    run_id = request.values.get("run_id", "")
    origin = get_safe_url(request.values.get("origin"))
    unpause = request.values.get("unpause")
    request_conf = request.values.get("conf")
    request_execution_date = request.values.get("execution_date", default=timezone.utcnow().isoformat())
    is_dag_run_conf_overrides_params = conf.getboolean("core", "dag_run_conf_overrides_params")
    dag = get_airflow_app().dag_bag.get_dag(dag_id)
    dag_orm: DagModel = session.query(DagModel).filter(DagModel.dag_id == dag_id).first()

    # Prepare form fields with param struct details to render a proper form with schema information
    form_fields = {}
    for k, v in dag.params.items():
        form_fields[k] = v.dump()
        # If no schema is provided, auto-detect on default values
        if "schema" not in form_fields[k]:
            form_fields[k]["schema"] = {}
        if "type" not in form_fields[k]["schema"]:
            if isinstance(form_fields[k]["value"], bool):
                form_fields[k]["schema"]["type"] = "boolean"
            elif isinstance(form_fields[k]["value"], int):
                form_fields[k]["schema"]["type"] = ["integer", "null"]
            elif isinstance(form_fields[k]["value"], list):
                form_fields[k]["schema"]["type"] = ["array", "null"]
            elif isinstance(form_fields[k]["value"], dict):
                form_fields[k]["schema"]["type"] = ["object", "null"]
        # Mark markup fields as safe
        if (
            "description_html" in form_fields[k]["schema"]
            and form_fields[k]["schema"]["description_html"]
        ):
            form_fields[k]["description"] = Markup(form_fields[k]["schema"]["description_html"])
        if "custom_html_form" in form_fields[k]["schema"]:
            form_fields[k]["schema"]["custom_html_form"] = Markup(
                form_fields[k]["schema"]["custom_html_form"]
            )

    if not dag_orm:
        flash(f"Cannot find dag {dag_id}")
        return redirect(origin)

    if dag_orm.has_import_errors:
        flash(f"Cannot create dagruns because the dag {dag_id} has import errors", "error")
        return redirect(origin)

    recent_runs = (
        session.query(
            DagRun.conf, func.max(DagRun.run_id).label("run_id"), func.max(DagRun.execution_date)
        )
        .filter(
            DagRun.dag_id == dag_id,
            DagRun.run_type == DagRunType.MANUAL,
            DagRun.conf.isnot(None),
        )
        .group_by(DagRun.conf)
        .order_by(func.max(DagRun.execution_date).desc())
        .limit(5)
        .all()
    )

    recent_confs = {}
    for run in recent_runs:
        recent_conf = getattr(run, "conf")
        if isinstance(recent_conf, dict) and any(recent_conf):
            recent_confs[getattr(run, "run_id")] = json.dumps(recent_conf)

    if request.method == "GET":
        # Populate conf textarea with conf requests parameter, or dag.params
        default_conf = ""

        doc_md = wwwutils.wrapped_markdown(getattr(dag, "doc_md", None))
        form = DateTimeForm(data={"execution_date": request_execution_date})

        if request_conf:
            default_conf = request_conf
        else:
            try:
                default_conf = json.dumps(
                    {str(k): v.resolve(suppress_exception=True) for k, v in dag.params.items()},
                    indent=4,
                    ensure_ascii=False,
                )
            except TypeError:
                flash("Could not pre-populate conf field due to non-JSON-serializable data-types")
        return self.render_template(
            "airflow/trigger.html",
            form_fields=form_fields,
            dag_id=dag_id,
            origin=origin,
            conf=default_conf,
            doc_md=doc_md,
            form=form,
            is_dag_run_conf_overrides_params=is_dag_run_conf_overrides_params,
            recent_confs=recent_confs,
        )

    try:
        execution_date = timezone.parse(request_execution_date)
    except ParserError:
        flash("Invalid execution date", "error")
        form = DateTimeForm(data={"execution_date": timezone.utcnow().isoformat()})
        return self.render_template(
            "airflow/trigger.html",
            form_fields=form_fields,
            dag_id=dag_id,
            origin=origin,
            conf=request_conf,
            form=form,
            is_dag_run_conf_overrides_params=is_dag_run_conf_overrides_params,
            recent_confs=recent_confs,
        )

    dr = DagRun.find_duplicate(dag_id=dag_id, run_id=run_id, execution_date=execution_date)
    if dr:
        if dr.run_id == run_id:
            message = f"The run ID {run_id} already exists"
        else:
            message = f"The logical date {execution_date} already exists"
        flash(message, "error")
        return redirect(origin)

    # Flash a warning when slash is used, but still allow it to continue on.
    if run_id and "/" in run_id:
        flash(
            "Using forward slash ('/') in a DAG run ID is deprecated. Note that this character "
            "also makes the run impossible to retrieve via Airflow's REST API.",
            "warning",
        )

    run_conf = {}
    if request_conf:
        try:
            run_conf = json.loads(request_conf)
            if not isinstance(run_conf, dict):
                flash("Invalid JSON configuration, must be a dict", "error")
                form = DateTimeForm(data={"execution_date": execution_date})
                return self.render_template(
                    "airflow/trigger.html",
                    form_fields=form_fields,
                    dag_id=dag_id,
                    origin=origin,
                    conf=request_conf,
                    form=form,
                    is_dag_run_conf_overrides_params=is_dag_run_conf_overrides_params,
                    recent_confs=recent_confs,
                )
        except json.decoder.JSONDecodeError:
            flash("Invalid JSON configuration, not parseable", "error")
            form = DateTimeForm(data={"execution_date": execution_date})
            return self.render_template(
                "airflow/trigger.html",
                form_fields=form_fields,
                dag_id=dag_id,
                origin=origin,
                conf=request_conf,
                form=form,
                is_dag_run_conf_overrides_params=is_dag_run_conf_overrides_params,
                recent_confs=recent_confs,
            )

    if unpause and dag.get_is_paused():
        dag_model = models.DagModel.get_dagmodel(dag_id)
        if dag_model is not None:
            dag_model.set_is_paused(is_paused=False)

    try:
        dag.create_dagrun(
            run_type=DagRunType.MANUAL,
            execution_date=execution_date,
            data_interval=dag.timetable.infer_manual_data_interval(run_after=execution_date),
            state=State.QUEUED,
            conf=run_conf,
            external_trigger=True,
            dag_hash=get_airflow_app().dag_bag.dags_hash.get(dag_id),
            run_id=run_id,
        )
    except (ValueError, ParamValidationError) as ve:
        flash(f"{ve}", "error")
        form = DateTimeForm(data={"execution_date": execution_date})
        # Take over "bad" submitted fields for new form display
        for k, v in form_fields.items():
            form_fields[k]["value"] = run_conf[k]
        return self.render_template(
            "airflow/trigger.html",
            form_fields=form_fields,
            dag_id=dag_id,
            origin=origin,
            conf=request_conf,
            form=form,
            is_dag_run_conf_overrides_params=is_dag_run_conf_overrides_params,
        )

    flash(f"Triggered {dag_id}, it should start any moment now.")
    return redirect(origin)

def wrapped_markdown(s, css_class="rich_doc"):
    """Convert a Markdown string to HTML."""
    md = MarkdownIt("gfm-like")
    if s is None:
        return None
    s = textwrap.dedent(s)
    return Markup(f'<div class="{css_class}" >{md.render(s)}</div>')

def search_datasets_handler():
    MAX_EXPERIMENT_IDS_PER_REQUEST = 20
    experiment_ids = request.json.get("experiment_ids", [])
    if not experiment_ids:
        raise MlflowException(
            message="SearchDatasets request must specify at least one experiment_id.",
            error_code=INVALID_PARAMETER_VALUE,
        )
    if len(experiment_ids) > MAX_EXPERIMENT_IDS_PER_REQUEST:
        raise MlflowException(
            message=(
                f"SearchDatasets request cannot specify more than {MAX_EXPERIMENT_IDS_PER_REQUEST}"
                f" experiment_ids. Received {len(experiment_ids)} experiment_ids."
            ),
            error_code=INVALID_PARAMETER_VALUE,
        )

    store = _get_tracking_store()

    if hasattr(store, "_search_datasets"):
        return {
            "dataset_summaries": [
                summary.to_dict() for summary in store._search_datasets(experiment_ids)
            ]
        }
    else:
        return _not_implemented()

def post(self, request, *args, **kwargs):
    content = request.POST.get("content", "")
    lexer = request.POST.get("lexer", highlight.LEXER_DEFAULT).strip()
    filename = request.POST.get("filename", "").strip()
    expires = request.POST.get("expires", "").strip()
    response_format = request.POST.get("format", "default").strip()

    if not content.strip():
        return HttpResponseBadRequest("No content given")

    # We need at least a lexer or a filename
    if not lexer and not filename:
        return HttpResponseBadRequest(
            "No lexer or filename given. Unable to "
            "determine a highlight. Valid lexers are: %s"
            % ", ".join(highlight.LEXER_KEYS)
        )

    # A lexer is given, check if its valid at all
    if lexer and lexer not in highlight.LEXER_KEYS:
        return HttpResponseBadRequest(
            'Invalid lexer "%s" given. Valid lexers are: %s'
            % (lexer, ", ".join(highlight.LEXER_KEYS))
        )

    # No lexer is given, but we have a filename, try to get the lexer
    #  out of it. In case Pygments cannot determine the lexer of the
    # filename, we fallback to 'plain' code.
    if not lexer and filename:
        try:
            lexer_cls = get_lexer_for_filename(filename)
            lexer = lexer_cls.aliases[0]
        except (ClassNotFound, IndexError):
            lexer = config.PLAIN_CODE_SYMBOL

    if expires:
        expire_options = [str(i) for i in dict(config.EXPIRE_CHOICES)]
        if expires not in expire_options:
            return HttpResponseBadRequest(
                'Invalid expire choice "{}" given. Valid values are: {}'.format(
                    expires, ", ".join(expire_options)
                )
            )
        expires, expire_type = get_expire_values(expires)
    else:
        expires = datetime.datetime.now() + datetime.timedelta(seconds=60 * 60 * 24)
        expire_type = Snippet.EXPIRE_TIME

    snippet = Snippet.objects.create(
        content=content,
        lexer=lexer,
        expires=expires,
        expire_type=expire_type,
    )

    # Custom formatter for the API response
    formatter = getattr(self, f"_format_{response_format}", None)
    if callable(formatter):
        return HttpResponse(formatter(snippet))

    # Otherwise use the default one.
    return HttpResponse(self._format_default(snippet))

def label_from_instance(self, obj):
    bits = []
    for ancestor in (
        obj.get_ancestors(inclusive=True).exclude(depth=1).specific(defer=True)
    ):
        bits.append(ancestor.get_admin_display_title())
    return mark_safe('<span class="icon icon-arrow-right"></span>'.join(bits))

