        bname = bname.strip(b" \t")
        bvalue = bvalue.lstrip()
        if HDRRE.search(bname):
            raise InvalidHeader(bname)
        if len(bname) > self.max_field_size:
            raise LineTooLong(
                "request header name {}".format(
                    bname.decode("utf8", "xmlcharrefreplace")
                ),
                str(self.max_field_size),
                str(len(bname)),
            )

        header_length = len(bvalue)

        # next line
        lines_idx += 1
        line = lines[lines_idx]

        # consume continuation lines
        continuation = line and line[0] in (32, 9)  # (' ', '\t')

        if continuation:
            bvalue_lst = [bvalue]
            while continuation:
                header_length += len(line)
                if header_length > self.max_field_size:
                    raise LineTooLong(
                        "request header field {}".format(
                            bname.decode("utf8", "xmlcharrefreplace")
                        ),
                        str(self.max_field_size),
                        str(header_length),
                    )
                bvalue_lst.append(line)

                # next line
                lines_idx += 1
                if lines_idx < line_count:
                    line = lines[lines_idx]
                    if line:
                        continuation = line[0] in (32, 9)  # (' ', '\t')
                else:
                    line = b""
                    break
            bvalue = b"".join(bvalue_lst)
        else:
            if header_length > self.max_field_size:
                raise LineTooLong(
                    "request header field {}".format(
                        bname.decode("utf8", "xmlcharrefreplace")
                    ),
                    str(self.max_field_size),
                    str(header_length),
                )

        bvalue = bvalue.strip()
        name = bname.decode("utf-8", "surrogateescape")
        value = bvalue.decode("utf-8", "surrogateescape")

        headers.add(name, value)
        raw_headers.append((bname, bvalue))

    return (CIMultiDictProxy(headers), tuple(raw_headers))

def post_create(self, icon):
    if EXITING:
        return  # to handle launch in pystray 'dummy' mode without --no-gui option (partial initialisation failure)

    if icon:
        icon.visible = True

    if not self.load_and_start_servers(icon, reload=False):
        return

    Log.info('Initialised', APP_NAME, '- listening for authentication requests')
    while True:
        data = REQUEST_QUEUE.get()  # note: blocking call
        if data is QUEUE_SENTINEL:  # app is closing
            break
        else:
            if not data['expired']:
                Log.info('Authorisation request received for', data['username'],
                         '(local server auth mode)' if self.args.local_server_auth else '(interactive mode)')
                if self.args.local_server_auth:
                    data['local_server_auth'] = True
                    RESPONSE_QUEUE.put(data)  # local server auth is handled by the client/server connections
                    self.notify(APP_NAME, 'Local server auth mode: please authorise a request for account %s' %
                                data['username'])
                elif icon:
                    self.authorisation_requests.append(data)
                    icon.update_menu()  # force refresh the menu
                    self.notify(APP_NAME, 'Please authorise your account %s from the menu' % data['username'])
            else:
                for request in self.authorisation_requests[:]:  # iterate over a copy; remove from original
                    if request['connection'] == data['connection']:
                        self.authorisation_requests.remove(request)
                        break

def get_oauth2_authorisation_code(permission_url, redirect_uri, redirect_listen_address, username, connection_info):
    """Submit an authorisation request to the parent app and block until it is provided (or the request fails)"""
    token_request = {'connection': connection_info, 'permission_url': permission_url,
                     'redirect_uri': redirect_uri, 'redirect_listen_address': redirect_listen_address,
                     'username': username, 'expired': False}
    REQUEST_QUEUE.put(token_request)
    wait_time = 0
    while True:
        try:
            data = RESPONSE_QUEUE.get(block=True, timeout=1)
        except queue.Empty:
            wait_time += 1
            if wait_time < AUTHENTICATION_TIMEOUT:
                continue
            else:
                token_request['expired'] = True
                if 'local_server_auth_wsgi' in token_request:
                    token_request['local_server_auth_wsgi'].server_close()
                REQUEST_QUEUE.put(token_request)  # re-insert the request as expired so the parent app can remove it
                return False, None

        if data is QUEUE_SENTINEL:  # app is closing
            RESPONSE_QUEUE.put(QUEUE_SENTINEL)  # make sure all watchers exit
            return False, None

        elif data['connection'] == connection_info:  # found an authentication response meant for us
            # to improve no-GUI mode we also support the use of a local server to receive the OAuth redirection
            # (note: not enabled by default because no-GUI mode is typically unattended, but useful in some cases)
            if 'local_server_auth' in data:
                threading.Thread(target=OAuth2Helper.start_redirection_receiver_server, args=(data,),
                                 name='EmailOAuth2Proxy-auth-%s' % data['username'], daemon=True).start()

            else:
                if 'response_url' in data and 'code=' in data['response_url']:
                    authorisation_code = OAuth2Helper.oauth2_url_unescape(
                        data['response_url'].split('code=')[1].split('&')[0])
                    if authorisation_code:
                        return True, authorisation_code
                return False, None

        else:  # not for this thread - put back into queue
            RESPONSE_QUEUE.put(data)
            time.sleep(1)

def send_headers(
    self,
    length: Optional[int],
    status: int = 200,
    mime: Optional[str] = None,
    headers: Optional[dict[str, str]] = None,
) -> None:
    response = ["%s %s %s" % (self.http_ver, status, HTTPCODE[status])]

    if length is not None:
        response.append("Content-Length: " + unicode(length))

    if status == 304 and self.k304():
        self.keepalive = False

    # close if unknown length, otherwise take client's preference
    response.append("Connection: " + ("Keep-Alive" if self.keepalive else "Close"))
    response.append("Date: " + formatdate(usegmt=True))

    # headers{} overrides anything set previously
    if headers:
        self.out_headers.update(headers)

    # default to utf8 html if no content-type is set
    if not mime:
        mime = self.out_headers.get("Content-Type") or "text/html; charset=utf-8"

    self.out_headers["Content-Type"] = mime

    for k, zs in list(self.out_headers.items()) + self.out_headerlist:
        response.append("%s: %s" % (k, zs))

    try:
        # best practice to separate headers and body into different packets
        self.s.sendall("\r\n".join(response).encode("utf-8") + b"\r\n\r\n")
    except:
        raise Pebkac(400, "client d/c while replying headers")

def createrepo_walker(self, repo, dirname, fnames):
    """
    Used to run createrepo on a copied Yum mirror.
    """
    if os.path.exists(dirname) or repo['breed'] == 'rsync':
        utils.remove_yum_olddata(dirname)

        # add any repo metadata we can use
        mdoptions = []
        if os.path.isfile("%s/.origin/repomd.xml" % (dirname)):
            if not HAS_YUM:
                utils.die(self.logger, "yum is required to use this feature")

            rmd = yum.repoMDObject.RepoMD('', "%s/.origin/repomd.xml" % (dirname))
            if "group" in rmd.repoData:
                groupmdfile = rmd.getData("group").location[1]
                mdoptions.append("-g %s" % groupmdfile)
            if "prestodelta" in rmd.repoData:
                # need createrepo >= 0.9.7 to add deltas
                if utils.get_family() in ("redhat", "suse"):
                    cmd = "/usr/bin/rpmquery --queryformat=%{VERSION} createrepo"
                    createrepo_ver = utils.subprocess_get(self.logger, cmd)
                    if utils.compare_versions_gt(createrepo_ver, "0.9.7"):
                        mdoptions.append("--deltas")
                    else:
                        self.logger.error("this repo has presto metadata; you must upgrade createrepo to >= 0.9.7 first and then need to resync the repo through cobbler.")

        blended = utils.blender(self.api, False, repo)
        flags = blended.get("createrepo_flags", "(ERROR: FLAGS)")
        try:
            # BOOKMARK
            cmd = "createrepo %s %s %s" % (" ".join(mdoptions), flags, dirname)
            utils.subprocess_call(self.logger, cmd)
        except:
            utils.log_exc(self.logger)
            self.logger.error("createrepo failed.")
        del fnames[:]           # we're in the right place

def yum_sync(self, repo):

    """
    Handle copying of http:// and ftp:// yum repos.
    """

    # create the config file the hosts will use to access the repository.
    repo_mirror = repo.mirror.strip()
    dest_path = os.path.join(self.settings.webdir + "/repo_mirror", repo.name.strip())
    self.create_local_file(dest_path, repo)

    if not repo.mirror_locally:
        return

    cmd = self.reposync_cmd()  # command to run
    has_rpm_list = False       # flag indicating not to pull the whole repo

    # detect cases that require special handling

    if repo.rpm_list != "" and repo.rpm_list != []:
        has_rpm_list = True

    # create yum config file for use by reposync
    temp_path = os.path.join(dest_path, ".origin")

    if not os.path.isdir(temp_path):
        # FIXME: there's a chance this might break the RHN D/L case
        os.makedirs(temp_path)

    temp_file = self.create_local_file(temp_path, repo, output=False)

    if not has_rpm_list:
        # if we have not requested only certain RPMs, use reposync
        cmd = "%s %s --config=%s --repoid=%s --download_path=%s" % (cmd, self.rflags, temp_file, repo.name, self.settings.webdir + "/repo_mirror")
        if repo.arch != "":
            if repo.arch == "x86":
                repo.arch = "i386"      # FIX potential arch errors
            if repo.arch == "i386":
                # counter-intuitive, but we want the newish kernels too
                cmd = "%s -a i686" % (cmd)
            else:
                cmd = "%s -a %s" % (cmd, repo.arch)

    else:

        # create the output directory if it doesn't exist
        if not os.path.exists(dest_path):
            os.makedirs(dest_path)

        use_source = ""
        if repo.arch == "src":
            use_source = "--source"

        # older yumdownloader sometimes explodes on --resolvedeps
        # if this happens to you, upgrade yum & yum-utils
        extra_flags = self.settings.yumdownloader_flags
        cmd = ""
        if os.path.exists("/usr/bin/dnf"):
            cmd = "/usr/bin/dnf download"
        else:
            cmd = "/usr/bin/yumdownloader"
        cmd = "%s %s %s --disablerepo=* --enablerepo=%s -c %s --destdir=%s %s" % (cmd, extra_flags, use_source, repo.name, temp_file, dest_path, " ".join(repo.rpm_list))

    # now regardless of whether we're doing yumdownloader or reposync
    # or whether the repo was http://, ftp://, or rhn://, execute all queued
    # commands here.  Any failure at any point stops the operation.

    rc = utils.subprocess_call(self.logger, cmd)
    if rc != 0:
        utils.die(self.logger, "cobbler reposync failed")

    repodata_path = os.path.join(dest_path, "repodata")

    # grab repomd.xml and use it to download any metadata we can use
    proxies = None
    if repo.proxy == '<<inherit>>':
        proxies = {'http': self.settings.proxy_url_ext}
    elif repo.proxy != '<<None>>' and repo.proxy != '':
        proxies = {'http': repo.proxy, 'https': repo.proxy}
    src = repo_mirror + "/repodata/repomd.xml"
    dst = temp_path + "/repomd.xml"
    urlgrab_ssl_opts = self.gen_urlgrab_ssl_opts(repo.yumopts)
    try:
        urlgrabber.grabber.urlgrab(src, filename=dst, proxies=proxies, **urlgrab_ssl_opts)
    except Exception as e:
        utils.die(self.logger, "failed to fetch " + src + " " + e.args)

    # create our repodata directory now, as any extra metadata we're
    # about to download probably lives there
    if not os.path.isdir(repodata_path):
        os.makedirs(repodata_path)
    rmd = yum.repoMDObject.RepoMD('', "%s/repomd.xml" % (temp_path))
    for mdtype in rmd.repoData.keys():
        # don't download metadata files that are created by default
        if mdtype not in ["primary", "primary_db", "filelists", "filelists_db", "other", "other_db"]:
            mdfile = rmd.getData(mdtype).location[1]
            src = repo_mirror + "/" + mdfile
            dst = dest_path + "/" + mdfile
            try:
                urlgrabber.grabber.urlgrab(src, filename=dst, proxies=proxies, **urlgrab_ssl_opts)
            except Exception as e:
                utils.die(self.logger, "failed to fetch " + src + " " + e.args)

    # now run createrepo to rebuild the index
    if repo.mirror_locally:
        os.path.walk(dest_path, self.createrepo_walker, repo)

def get_logs_with_metadata(self, session: Session = NEW_SESSION):
    """Retrieve logs including metadata."""
    dag_id = request.args.get("dag_id")
    task_id = request.args.get("task_id")
    execution_date_str = request.args["execution_date"]
    map_index = request.args.get("map_index", -1, type=int)
    try_number = request.args.get("try_number", type=int)
    metadata_str = request.args.get("metadata", "{}")
    response_format = request.args.get("format", "json")

    # Validate JSON metadata
    try:
        metadata: dict = json.loads(metadata_str) or {}
    except json.decoder.JSONDecodeError:
        return {"error": "Invalid JSON metadata"}, 400

    # Convert string datetime into actual datetime
    try:
        execution_date = timezone.parse(execution_date_str)
    except ValueError:
        error_message = (
            f"Given execution date, {execution_date}, could not be identified as a date. "
            "Example date format: 2015-11-16T14:34:15+00:00"
        )
        return {"error": error_message}, 400

    task_log_reader = TaskLogReader()
    if not task_log_reader.supports_read:
        return {
            "message": "Task log handler does not support read logs.",
            "error": True,
            "metadata": {"end_of_log": True},
        }

    ti = session.scalar(
        select(models.TaskInstance)
        .where(
            TaskInstance.task_id == task_id,
            TaskInstance.dag_id == dag_id,
            TaskInstance.execution_date == execution_date,
            TaskInstance.map_index == map_index,
        )
        .join(TaskInstance.dag_run)
        .options(joinedload(TaskInstance.trigger).joinedload(Trigger.triggerer_job))
        .limit(1)
    )

    if ti is None:
        return {
            "message": "*** Task instance did not exist in the DB\n",
            "error": True,
            "metadata": {"end_of_log": True},
        }

    try:
        dag = get_airflow_app().dag_bag.get_dag(dag_id)
        if dag:
            ti.task = dag.get_task(ti.task_id)

        if response_format == "json":
            logs, metadata = task_log_reader.read_log_chunks(ti, try_number, metadata)
            message = logs[0] if try_number is not None else logs
            return {"message": message, "metadata": metadata}

        metadata["download_logs"] = True
        attachment_filename = task_log_reader.render_log_filename(ti, try_number, session=session)
        log_stream = task_log_reader.read_log_stream(ti, try_number, metadata)
        return Response(
            response=log_stream,
            mimetype="text/plain",
            headers={"Content-Disposition": f"attachment; filename={attachment_filename}"},
        )
    except AttributeError as e:
        error_messages = [f"Task log handler does not support read logs.\n{str(e)}\n"]
        metadata["end_of_log"] = True
        return {"message": error_messages, "error": True, "metadata": metadata}

def grid_data(self):
    """Returns grid data."""
    dag_id = request.args.get("dag_id")
    dag = get_airflow_app().dag_bag.get_dag(dag_id)

    if not dag:
        return {"error": f"can't find dag {dag_id}"}, 404

    root = request.args.get("root")
    if root:
        filter_upstream = request.args.get("filter_upstream") == "true"
        filter_downstream = request.args.get("filter_downstream") == "true"
        dag = dag.partial_subset(
            task_ids_or_regex=root, include_upstream=filter_upstream, include_downstream=filter_downstream
        )

    num_runs = request.args.get("num_runs", type=int)
    if num_runs is None:
        num_runs = conf.getint("webserver", "default_dag_run_display_number")

    try:
        base_date = timezone.parse(request.args["base_date"])
    except (KeyError, ValueError):
        base_date = dag.get_latest_execution_date() or timezone.utcnow()

    with create_session() as session:
        query = select(DagRun).where(DagRun.dag_id == dag.dag_id, DagRun.execution_date <= base_date)

    run_type = request.args.get("run_type")
    if run_type:
        query = query.where(DagRun.run_type == run_type)

    run_state = request.args.get("run_state")
    if run_state:
        query = query.where(DagRun.state == run_state)

    dag_runs = wwwutils.sorted_dag_runs(
        query, ordering=dag.timetable.run_ordering, limit=num_runs, session=session
    )
    encoded_runs = [wwwutils.encode_dag_run(dr, json_encoder=utils_json.WebEncoder) for dr in dag_runs]
    data = {
        "groups": dag_to_grid(dag, dag_runs, session),
        "dag_runs": encoded_runs,
        "ordering": dag.timetable.run_ordering,
    }
    # avoid spaces to reduce payload size
    return (
        htmlsafe_json_dumps(data, separators=(",", ":"), dumps=flask.json.dumps),
        {"Content-Type": "application/json; charset=utf-8"},
    )

def _call_downloader(self, tmpfilename, info_dict):
    ffpp = FFmpegPostProcessor(downloader=self)
    if not ffpp.available:
        self.report_error('m3u8 download detected but ffmpeg could not be found. Please install')
        return False
    ffpp.check_version()

    args = [ffpp.executable, '-y']

    for log_level in ('quiet', 'verbose'):
        if self.params.get(log_level, False):
            args += ['-loglevel', log_level]
            break
    if not self.params.get('verbose'):
        args += ['-hide_banner']

    args += traverse_obj(info_dict, ('downloader_options', 'ffmpeg_args'), default=[])

    # These exists only for compatibility. Extractors should use
    # info_dict['downloader_options']['ffmpeg_args'] instead
    args += info_dict.get('_ffmpeg_args') or []
    seekable = info_dict.get('_seekable')
    if seekable is not None:
        # setting -seekable prevents ffmpeg from guessing if the server
        # supports seeking(by adding the header `Range: bytes=0-`), which
        # can cause problems in some cases
        # https://github.com/ytdl-org/youtube-dl/issues/11800#issuecomment-275037127
        # http://trac.ffmpeg.org/ticket/6125#comment:10
        args += ['-seekable', '1' if seekable else '0']

    env = None
    proxy = self.params.get('proxy')
    if proxy:
        if not re.match(r'^[\da-zA-Z]+://', proxy):
            proxy = 'http://%s' % proxy

        if proxy.startswith('socks'):
            self.report_warning(
                '%s does not support SOCKS proxies. Downloading is likely to fail. '
                'Consider adding --hls-prefer-native to your command.' % self.get_basename())

        # Since December 2015 ffmpeg supports -http_proxy option (see
        # http://git.videolan.org/?p=ffmpeg.git;a=commit;h=b4eb1f29ebddd60c41a2eb39f5af701e38e0d3fd)
        # We could switch to the following code if we are able to detect version properly
        # args += ['-http_proxy', proxy]
        env = os.environ.copy()
        env['HTTP_PROXY'] = proxy
        env['http_proxy'] = proxy

    protocol = info_dict.get('protocol')

    if protocol == 'rtmp':
        player_url = info_dict.get('player_url')
        page_url = info_dict.get('page_url')
        app = info_dict.get('app')
        play_path = info_dict.get('play_path')
        tc_url = info_dict.get('tc_url')
        flash_version = info_dict.get('flash_version')
        live = info_dict.get('rtmp_live', False)
        conn = info_dict.get('rtmp_conn')
        if player_url is not None:
            args += ['-rtmp_swfverify', player_url]
        if page_url is not None:
            args += ['-rtmp_pageurl', page_url]
        if app is not None:
            args += ['-rtmp_app', app]
        if play_path is not None:
            args += ['-rtmp_playpath', play_path]
        if tc_url is not None:
            args += ['-rtmp_tcurl', tc_url]
        if flash_version is not None:
            args += ['-rtmp_flashver', flash_version]
        if live:
            args += ['-rtmp_live', 'live']
        if isinstance(conn, list):
            for entry in conn:
                args += ['-rtmp_conn', entry]
        elif isinstance(conn, str):
            args += ['-rtmp_conn', conn]

    start_time, end_time = info_dict.get('section_start') or 0, info_dict.get('section_end')

    selected_formats = info_dict.get('requested_formats') or [info_dict]
    for i, fmt in enumerate(selected_formats):
        if fmt.get('http_headers') and re.match(r'^https?://', fmt['url']):
            # Trailing \r\n after each HTTP header is important to prevent warning from ffmpeg/avconv:
            # [http @ 00000000003d2fa0] No trailing CRLF found in HTTP header.
            args.extend(['-headers', ''.join(f'{key}: {val}\r\n' for key, val in fmt['http_headers'].items())])

        if start_time:
            args += ['-ss', str(start_time)]
        if end_time:
            args += ['-t', str(end_time - start_time)]

        args += self._configuration_args((f'_i{i + 1}', '_i')) + ['-i', fmt['url']]

    if not (start_time or end_time) or not self.params.get('force_keyframes_at_cuts'):
        args += ['-c', 'copy']

    if info_dict.get('requested_formats') or protocol == 'http_dash_segments':
        for i, fmt in enumerate(selected_formats):
            stream_number = fmt.get('manifest_stream_number', 0)
            args.extend(['-map', f'{i}:{stream_number}'])

    if self.params.get('test', False):
        args += ['-fs', str(self._TEST_FILE_SIZE)]

    ext = info_dict['ext']
    if protocol in ('m3u8', 'm3u8_native'):
        use_mpegts = (tmpfilename == '-') or self.params.get('hls_use_mpegts')
        if use_mpegts is None:
            use_mpegts = info_dict.get('is_live')
        if use_mpegts:
            args += ['-f', 'mpegts']
        else:
            args += ['-f', 'mp4']
            if (ffpp.basename == 'ffmpeg' and ffpp._features.get('needs_adtstoasc')) and (not info_dict.get('acodec') or info_dict['acodec'].split('.')[0] in ('aac', 'mp4a')):
                args += ['-bsf:a', 'aac_adtstoasc']
    elif protocol == 'rtmp':
        args += ['-f', 'flv']
    elif ext == 'mp4' and tmpfilename == '-':
        args += ['-f', 'mpegts']
    elif ext == 'unknown_video':
        ext = determine_ext(remove_end(tmpfilename, '.part'))
        if ext == 'unknown_video':
            self.report_warning(
                'The video format is unknown and cannot be downloaded by ffmpeg. '
                'Explicitly set the extension in the filename to attempt download in that format')
        else:
            self.report_warning(f'The video format is unknown. Trying to download as {ext} according to the filename')
            args += ['-f', EXT_TO_OUT_FORMATS.get(ext, ext)]
    else:
        args += ['-f', EXT_TO_OUT_FORMATS.get(ext, ext)]

    args += self._configuration_args(('_o1', '_o', ''))

    args = [encodeArgument(opt) for opt in args]
    args.append(encodeFilename(ffpp._ffmpeg_filename_argument(tmpfilename), True))
    self._debug_cmd(args)

    piped = any(fmt['url'] in ('-', 'pipe:') for fmt in selected_formats)
    with Popen(args, stdin=subprocess.PIPE, env=env) as proc:
        if piped:
            self.on_process_started(proc, proc.stdin)
        try:
            retval = proc.wait()
        except BaseException as e:
            # subprocces.run would send the SIGKILL signal to ffmpeg and the
            # mp4 file couldn't be played, but if we ask ffmpeg to quit it
            # produces a file that is playable (this is mostly useful for live
            # streams). Note that Windows is not affected and produces playable
            # files (see https://github.com/ytdl-org/youtube-dl/issues/8300).
            if isinstance(e, KeyboardInterrupt) and sys.platform != 'win32' and not piped:
                proc.communicate_or_kill(b'q')
            else:
                proc.kill(timeout=None)
            raise
        return retval

def real_download(self, filename, info_dict):
    self.report_destination(filename)
    tmpfilename = self.temp_name(filename)

    try:
        started = time.time()
        retval = self._call_downloader(tmpfilename, info_dict)
    except KeyboardInterrupt:
        if not info_dict.get('is_live'):
            raise
        # Live stream downloading cancellation should be considered as
        # correct and expected termination thus all postprocessing
        # should take place
        retval = 0
        self.to_screen('[%s] Interrupted by user' % self.get_basename())

    if retval == 0:
        status = {
            'filename': filename,
            'status': 'finished',
            'elapsed': time.time() - started,
        }
        if filename != '-':
            fsize = os.path.getsize(encodeFilename(tmpfilename))
            self.try_rename(tmpfilename, filename)
            status.update({
                'downloaded_bytes': fsize,
                'total_bytes': fsize,
            })
        self._hook_progress(status, info_dict)
        return True
    else:
        self.to_stderr('\n')
        self.report_error('%s exited with code %d' % (
            self.get_basename(), retval))
        return False

def _make_cmd(self, tmpfilename, info_dict):
    cmd = [self.exe, '-O', tmpfilename, '-nv', '--no-cookies', '--compression=auto']
    if info_dict.get('http_headers') is not None:
        for key, val in info_dict['http_headers'].items():
            cmd += ['--header', f'{key}: {val}']
    cmd += self._option('--limit-rate', 'ratelimit')
    retry = self._option('--tries', 'retries')
    if len(retry) == 2:
        if retry[1] in ('inf', 'infinite'):
            retry[1] = '0'
        cmd += retry
    cmd += self._option('--bind-address', 'source_address')
    proxy = self.params.get('proxy')
    if proxy:
        for var in ('http_proxy', 'https_proxy'):
            cmd += ['--execute', f'{var}={proxy}']
    cmd += self._valueless_option('--no-check-certificate', 'nocheckcertificate')
    cmd += self._configuration_args()
    cmd += ['--', info_dict['url']]
    return cmd

def __extract_info(self, url, ie, download, extra_info, process):
    try:
        ie_result = ie.extract(url)
    except UserNotLive as e:
        if process:
            if self.params.get('wait_for_video'):
                self.report_warning(e)
            self._wait_for_video()
        raise
    if ie_result is None:  # Finished already (backwards compatibility; listformats and friends should be moved here)
        self.report_warning(f'Extractor {ie.IE_NAME} returned nothing{bug_reports_message()}')
        return
    if isinstance(ie_result, list):
        # Backwards compatibility: old IE result format
        ie_result = {
            '_type': 'compat_list',
            'entries': ie_result,
        }
    if extra_info.get('original_url'):
        ie_result.setdefault('original_url', extra_info['original_url'])
    self.add_default_extra_info(ie_result, ie, url)
    if process:
        self._wait_for_video(ie_result)
        return self.process_ie_result(ie_result, download, extra_info)
    else:
        return ie_result

def download_with_info_file(self, info_filename):
    with contextlib.closing(fileinput.FileInput(
            [info_filename], mode='r',
            openhook=fileinput.hook_encoded('utf-8'))) as f:
        # FileInput doesn't have a read method, we can't call json.load
        infos = [self.sanitize_info(info, self.params.get('clean_infojson', True))
                 for info in variadic(json.loads('\n'.join(f)))]
    for info in infos:
        try:
            self.__download_wrapper(self.process_ie_result)(info, download=True)
        except (DownloadError, EntryNotInPlaylist, ReExtractInfo) as e:
            if not isinstance(e, EntryNotInPlaylist):
                self.to_stderr('\r')
            webpage_url = info.get('webpage_url')
            if webpage_url is None:
                raise
            self.report_warning(f'The info failed to download: {e}; trying with URL {webpage_url}')
            self.download([webpage_url])
    return self._download_retcode

def _calc_headers(self, info_dict):
    res = merge_headers(self.params['http_headers'], info_dict.get('http_headers') or {})
    if 'Youtubedl-No-Compression' in res:  # deprecated
        res.pop('Youtubedl-No-Compression', None)
        res['Accept-Encoding'] = 'identity'
    cookies = self.cookiejar.get_cookie_header(info_dict['url'])
    if cookies:
        res['Cookie'] = cookies

    if 'X-Forwarded-For' not in res:
        x_forwarded_for_ip = info_dict.get('__x_forwarded_for_ip')
        if x_forwarded_for_ip:
            res['X-Forwarded-For'] = x_forwarded_for_ip

    return res

def handle_logged_in(self, request, conn, connector):
    """
    We override this to provide webclient-specific functionality
    such as cleaning up any previous sessions (if user didn't logout)
    and redirect to specified url or webclient index page.
    """

    # webclient has various state that needs cleaning up...
    # if 'active_group' remains in session from previous
    # login, check it's valid for this user
    # NB: we do this for public users in @login_required.get_connection()
    if request.session.get("active_group"):
        if (
            request.session.get("active_group")
            not in conn.getEventContext().memberOfGroups
        ):
            del request.session["active_group"]
    if request.session.get("user_id"):
        # always want to revert to logged-in user
        del request.session["user_id"]
    if request.session.get("server_settings"):
        # always clean when logging in
        del request.session["server_settings"]
    # do we ned to display server version ?
    # server_version = conn.getServerVersion()
    if request.POST.get("noredirect"):
        return HttpResponse("OK")
    url = request.GET.get("url")
    if url is None or len(url) == 0:
        try:
            url = parse_url(settings.LOGIN_REDIRECT)
        except Exception:
            url = reverse("webindex")
    return HttpResponseRedirect(url)

def _extract_single(
    self,
    fp: BinaryIO,
    files,
    src_end: int,
    q: Optional[queue.Queue],
    skip_notarget=True,
) -> None:
    """
    Single thread extractor that takes file lists in single 7zip folder.
    this may raise exception.
    """
    just_check: List[ArchiveFile] = []
    for f in files:
        if q is not None:
            q.put(
                (
                    "s",
                    str(f.filename),
                    str(f.compressed) if f.compressed is not None else "0",
                )
            )
        fileish = self.target_filepath.get(f.id, None)
        if fileish is None:
            if not f.emptystream:
                just_check.append(f)
        else:
            # delayed execution of crc check.
            self._check(fp, just_check, src_end)
            just_check = []
            fileish.parent.mkdir(parents=True, exist_ok=True)
            if not f.emptystream:
                if f.is_junction and not isinstance(fileish, MemIO) and sys.platform == "win32":
                    with io.BytesIO() as ofp:
                        self.decompress(fp, f.folder, ofp, f.uncompressed, f.compressed, src_end)
                        dst: str = ofp.read().decode("utf-8")
                        # fileish.unlink(missing_ok=True) > py3.7
                        if fileish.exists():
                            fileish.unlink()
                        if sys.platform == "win32":  # hint for mypy
                            _winapi.CreateJunction(str(fileish), dst)  # noqa
                elif f.is_symlink and not isinstance(fileish, MemIO):
                    with io.BytesIO() as omfp:
                        self.decompress(fp, f.folder, omfp, f.uncompressed, f.compressed, src_end)
                        omfp.seek(0)
                        sym_target = pathlib.Path(omfp.read().decode("utf-8"))
                        # fileish.unlink(missing_ok=True) > py3.7
                        if fileish.exists():
                            fileish.unlink()
                        fileish.symlink_to(sym_target)
                else:
                    with fileish.open(mode="wb") as obfp:
                        crc32 = self.decompress(fp, f.folder, obfp, f.uncompressed, f.compressed, src_end)
                        obfp.seek(0)
                        if f.crc32 is not None and crc32 != f.crc32:
                            raise CrcError(crc32, f.crc32, f.filename)
            else:
                # just create empty file
                if not isinstance(fileish, MemIO):
                    fileish.touch()
                else:
                    with fileish.open() as ofp:
                        pass
        if q is not None:
            q.put(("e", str(f.filename), str(f.uncompressed)))
    if not skip_notarget:
        # delayed execution of crc check.
        self._check(fp, just_check, src_end)

def _extract(
    self,
    path: Optional[Any] = None,
    targets: Optional[List[str]] = None,
    return_dict: bool = False,
    callback: Optional[ExtractCallback] = None,
) -> Optional[Dict[str, IO[Any]]]:
    if callback is None:
        pass
    elif isinstance(callback, ExtractCallback):
        self.reporterd = Thread(target=self.reporter, args=(callback,), daemon=True)
        self.reporterd.start()
    else:
        raise ValueError("Callback specified is not an instance of subclass of py7zr.callbacks.ExtractCallback class")
    target_files: List[Tuple[pathlib.Path, Dict[str, Any]]] = []
    target_dirs: List[pathlib.Path] = []
    if path is not None:
        if isinstance(path, str):
            path = pathlib.Path(path)
        try:
            if not path.exists():
                path.mkdir(parents=True)
            else:
                pass
        except OSError as e:
            if e.errno == errno.EEXIST and path.is_dir():
                pass
            else:
                raise e
    fnames: List[str] = []  # check duplicated filename in one archive?
    self.q.put(("pre", None, None))
    for f in self.files:
        # When archive has a multiple files which have same name
        # To guarantee order of archive, multi-thread decompression becomes off.
        # Currently always overwrite by latter archives.
        # TODO: provide option to select overwrite or skip.
        if f.filename not in fnames:
            outname = f.filename
        else:
            i = 0
            while True:
                outname = f.filename + "_%d" % i
                if outname not in fnames:
                    break
                i += 1
        fnames.append(outname)
        # check f.filename has invalid directory traversals
        if path is None:
            # do following but is_relative_to introduced in py 3.9
            # so I replaced it with relative_to. when condition is not satisfied, raise ValueError
            # if not pathlib.Path(...).joinpath(remove_relative_path_marker(outname)).is_relative_to(...):
            #    raise Bad7zFile
            try:
                pathlib.Path(os.getcwd()).joinpath(remove_relative_path_marker(outname)).relative_to(os.getcwd())
            except ValueError:
                raise Bad7zFile
            outfilename = pathlib.Path(remove_relative_path_marker(outname))
        else:
            outfilename = path.joinpath(remove_relative_path_marker(outname))
            try:
                outfilename.relative_to(path)
            except ValueError:
                raise Bad7zFile
        # When python on Windows and not python on Cygwin,
        # Add win32 file namespace to exceed microsoft windows
        # path length limitation to 260 bytes
        # ref.
        # https://docs.microsoft.com/en-us/windows/win32/fileio/naming-a-file
        # In editions of Windows before Windows 10 version 1607,
        # the maximum length for a path is MAX_PATH, which is defined as
        # 260 characters. In later versions of Windows, changing a registry key
        # or select option when python installation is required to remove the limit.
        if is_windows_native_python() and outfilename.is_absolute() and not is_windows_unc_path(outfilename):
            outfilename = pathlib.WindowsPath("\\\\?\\" + str(outfilename))
        if targets is not None and f.filename not in targets:
            self.worker.register_filelike(f.id, None)
            continue
        if return_dict:
            if f.is_directory or f.is_socket:
                # ignore special files and directories
                pass
            else:
                fname = outfilename.as_posix()
                _buf = io.BytesIO()
                self._dict[fname] = _buf
                self.worker.register_filelike(f.id, MemIO(_buf))
        elif f.is_directory:
            if not outfilename.exists():
                target_dirs.append(outfilename)
                target_files.append((outfilename, f.file_properties()))
            else:
                pass
        elif f.is_socket:
            pass  # TODO: implement me.
        elif f.is_symlink or f.is_junction:
            self.worker.register_filelike(f.id, outfilename)
        else:
            self.worker.register_filelike(f.id, outfilename)
            target_files.append((outfilename, f.file_properties()))
    for target_dir in sorted(target_dirs):
        try:
            target_dir.mkdir(parents=True)
        except FileExistsError:
            if target_dir.is_dir():
                pass
            elif target_dir.is_file():
                raise DecompressionError("Directory {} is existed as a normal file.".format(str(target_dir)))
            else:
                raise DecompressionError("Directory {} making fails on unknown condition.".format(str(target_dir)))

    if callback is not None:
        self.worker.extract(
            self.fp,
            parallel=(not self.password_protected and not self._filePassed),
            q=self.q,
        )
    else:
        self.worker.extract(
            self.fp,
            parallel=(not self.password_protected and not self._filePassed),
        )

    self.q.put(("post", None, None))
    # early return when dict specified
    if return_dict:
        return self._dict
    # set file properties
    for outfilename, properties in target_files:
        # mtime
        lastmodified = None
        try:
            lastmodified = ArchiveTimestamp(properties["lastwritetime"]).totimestamp()
        except KeyError:
            pass
        if lastmodified is not None:
            os.utime(str(outfilename), times=(lastmodified, lastmodified))
        if os.name == "posix":
            st_mode = properties["posix_mode"]
            if st_mode is not None:
                outfilename.chmod(st_mode)
                continue
        # fallback: only set readonly if specified
        if properties["readonly"] and not properties["is_directory"]:
            ro_mask = 0o777 ^ (stat.S_IWRITE | stat.S_IWGRP | stat.S_IWOTH)
            outfilename.chmod(outfilename.stat().st_mode & ro_mask)
    return None

def extract(self, fp: BinaryIO, parallel: bool, skip_notarget=True, q=None) -> None:
    """Extract worker method to handle 7zip folder and decompress each files."""
    if hasattr(self.header, "main_streams") and self.header.main_streams is not None:
        src_end = self.src_start + self.header.main_streams.packinfo.packpositions[-1]
        numfolders = self.header.main_streams.unpackinfo.numfolders
        if numfolders == 1:
            self.extract_single(
                fp,
                self.files,
                self.src_start,
                src_end,
                q,
                skip_notarget=skip_notarget,
            )
        else:
            folders = self.header.main_streams.unpackinfo.folders
            positions = self.header.main_streams.packinfo.packpositions
            empty_files = [f for f in self.files if f.emptystream]
            if not parallel:
                self.extract_single(fp, empty_files, 0, 0, q)
                for i in range(numfolders):
                    if skip_notarget:
                        if not any([self.target_filepath.get(f.id, None) for f in folders[i].files]):
                            continue
                    self.extract_single(
                        fp,
                        folders[i].files,
                        self.src_start + positions[i],
                        self.src_start + positions[i + 1],
                        q,
                        skip_notarget=skip_notarget,
                    )
            else:
                if getattr(fp, "name", None) is None:
                    raise InternalError("Caught unknown variable status error")
                filename: str = getattr(fp, "name", "")  # do not become "" but it is for type check.
                self.extract_single(open(filename, "rb"), empty_files, 0, 0, q)
                concurrent_tasks = []
                exc_q: queue.Queue = queue.Queue()
                for i in range(numfolders):
                    if skip_notarget:
                        if not any([self.target_filepath.get(f.id, None) for f in folders[i].files]):
                            continue
                    p = self.concurrent(
                        target=self.extract_single,
                        args=(
                            filename,
                            folders[i].files,
                            self.src_start + positions[i],
                            self.src_start + positions[i + 1],
                            q,
                            exc_q,
                            skip_notarget,
                        ),
                    )
                    p.start()
                    concurrent_tasks.append(p)
                for p in concurrent_tasks:
                    p.join()
                if exc_q.empty():
                    pass
                else:
                    exc_info = exc_q.get()
                    raise exc_info[1].with_traceback(exc_info[2])
    else:
        empty_files = [f for f in self.files if f.emptystream]
        self.extract_single(fp, empty_files, 0, 0, q)

def writestr(self, data: Union[str, bytes, bytearray, memoryview], arcname: str):
    if not isinstance(arcname, str):
        raise ValueError("Unsupported arcname")
    if isinstance(data, str):
        self.writef(io.BytesIO(data.encode("UTF-8")), arcname)
    elif isinstance(data, bytes) or isinstance(data, bytearray) or isinstance(data, memoryview):
        self.writef(io.BytesIO(data), arcname)
    else:
        raise ValueError("Unsupported data type.")

def from_yaml(self, content):
    """
    Given some YAML data, returns a Python dictionary of the decoded data.
    """
    if yaml is None:
        raise ImproperlyConfigured("Usage of the YAML aspects requires yaml.")

    return yaml.load(content)

def project_clone(request):
    """
    clone project from github
    :param request: request object
    :return: json
    """
    if request.method == 'POST':
        data = json.loads(request.body)
        address = data.get('address')
        if not address.startswith('http'):
            return JsonResponse({'status': False})
        address = address + '.git' if not address.endswith('.git') else address
        cmd = 'git clone {address} {target}'.format(address=address, target=join(PROJECTS_FOLDER, Path(address).stem))
        logger.debug('clone cmd %s', cmd)
        p = Popen(cmd, shell=True, stdin=PIPE, stdout=PIPE, stderr=PIPE)
        stdout, stderr = bytes2str(p.stdout.read()), bytes2str(p.stderr.read())
        logger.debug('clone run result %s', stdout)
        if stderr: logger.error(stderr)
        return JsonResponse({'status': True}) if not stderr else JsonResponse({'status': False})

